import{m as t,g as a,i as s,y as o}from"./chunks/framework.CyQWWwrP.js";const g=JSON.parse('{"title":"Migrating an Existing Application","description":"","frontmatter":{},"headers":[],"relativePath":"guidance/migration.md","filePath":"guidance/migration.md"}'),i={name:"guidance/migration.md"};function n(r,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="migrating-an-existing-application" tabindex="-1">Migrating an Existing Application <a class="header-anchor" href="#migrating-an-existing-application" aria-label="Permalink to &quot;Migrating an Existing Application&quot;">​</a></h1><p>Migration to Cobalt should be scoped and incremental. Bootstrap, Angular, MUI, custom CSS, and local component libraries can all coexist with Cobalt while the design system matures.</p><p>This is not a full Bootstrap or Angular transition guide. It is a practical path for moving one workflow or route at a time.</p><h2 id="recommended-path" tabindex="-1">Recommended Path <a class="header-anchor" href="#recommended-path" aria-label="Permalink to &quot;Recommended Path&quot;">​</a></h2><ol><li><strong>Choose a slice.</strong> Pick one route, workflow, or page region with manageable risk.</li><li><strong>Install foundations.</strong> Add <code>@cobalt/tokens</code>, import token CSS, and verify import order.</li><li><strong>Tokenize local CSS.</strong> Replace obvious hard-coded colors, spacing, type, radius, and focus values with semantic tokens.</li><li><strong>Apply element mapping.</strong> Add <code>@cobalt/tokens/css/base</code> and scope <code>[data-co-base]</code> to the slice.</li><li><strong>Adopt ready components.</strong> Replace only components that have acceptable docs, status, wrapper behavior, and accessibility support.</li><li><strong>Verify and expand.</strong> Test the slice, document gaps, then repeat on the next surface.</li></ol><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Using agentic coding tools?</p><p>Install the Cobalt agent skill so Claude Code and OpenAI Codex query the <code>co</code> CLI as the source of truth during migration: <code>co skill add</code>. See <a href="/cobalt-design-system/resources/cli.html#manage-the-cobalt-skill">Manage the Cobalt Skill</a>.</p></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">npm</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> @cobalt/tokens</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> @cobalt/components</span></span></code></pre></div><p>Add a framework wrapper when useful:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">npm</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> @cobalt/react</span></span>
<span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">npm</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> @cobalt/vue</span></span>
<span class="line"><span style="--shiki-dark:#FFB757;--shiki-light:#6F42C1;">npm</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> install</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> @cobalt/angular</span></span></code></pre></div><p>Load foundations in order:</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#FF9492;--shiki-light:#D73A49;">@import</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> &#39;@cobalt/tokens/css&#39;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">;</span></span>
<span class="line"><span style="--shiki-dark:#FF9492;--shiki-light:#D73A49;">@import</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> &#39;@cobalt/tokens/css/fonts&#39;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">;</span></span>
<span class="line"><span style="--shiki-dark:#FF9492;--shiki-light:#D73A49;">@import</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> &#39;@cobalt/tokens/css/base&#39;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">;</span></span>
<span class="line"><span style="--shiki-dark:#FF9492;--shiki-light:#D73A49;">@import</span><span style="--shiki-dark:#ADDCFF;--shiki-light:#032F62;"> &#39;@cobalt/components/pre-upgrade.css&#39;</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">;</span></span></code></pre></div><p>The order matters: tokens must be parsed first so the <code>var(--co-*)</code> references inside <code>pre-upgrade.css</code> resolve at first paint.</p><h3 id="suppressing-flash-of-unstyled-content" tabindex="-1">Suppressing flash-of-unstyled-content <a class="header-anchor" href="#suppressing-flash-of-unstyled-content" aria-label="Permalink to &quot;Suppressing flash-of-unstyled-content&quot;">​</a></h3><p>Cobalt components are built with Lit, which means each <code>&lt;co-*&gt;</code> element only acquires its styles after the browser parses the HTML, downloads the component bundle, runs <code>customElements.define()</code>, and attaches the element&#39;s shadow DOM. During a fresh-project bootstrap the user typically does not notice the gap — the whole page is loading. During an incremental migration the gap is far more visible: the host application is already painted and styled, then individual <code>&lt;co-*&gt;</code> tags inside the migrated slice appear with <code>display: inline</code> and no styling for tens to hundreds of milliseconds before snapping into their upgraded shape. The result reads as a layout shift on every navigation into the slice.</p><p><code>@cobalt/components/pre-upgrade.css</code> ships one <code>:not(:defined)</code> rule per Cobalt tag in the <code>co.reset</code> cascade layer. Each rule does two things:</p><ul><li><strong>Reserves the layout</strong> the upgraded <code>:host</code> will occupy (<code>display</code>, <code>inline-size</code>/<code>block-size</code>, <code>vertical-align</code> — sourced from each component&#39;s <code>:host</code> block).</li><li><strong>Hides slotted content</strong> via <code>visibility: hidden;</code> so plain-text fallback inside <code>&lt;co-button&gt;Loading&lt;/co-button&gt;</code> is not painted before the component renders it.</li></ul><p>When the browser registers each element, <code>:not(:defined)</code> stops matching and the shadow-DOM <code>:host</code> styles take over with no visible shift.</p><h4 id="integrating-into-your-build" tabindex="-1">Integrating into your build <a class="header-anchor" href="#integrating-into-your-build" aria-label="Permalink to &quot;Integrating into your build&quot;">​</a></h4><p>Pick the path that matches the migrated slice&#39;s existing entrypoint:</p><ul><li><strong>Plain CSS or a global stylesheet</strong> — keep the <code>@import</code> shown above.</li><li><strong>SCSS</strong> — keep <code>@use &#39;@cobalt/tokens/scss&#39; as co;</code> for the Sass helpers, then add <code>@import &#39;@cobalt/components/pre-upgrade.css&#39;;</code> next to the other token CSS imports. (Sass passes <code>@import</code> of a plain <code>.css</code> file through as a CSS <code>@import url(...)</code>, which the bundler resolves through <code>node_modules</code>.)</li><li><strong>JavaScript entrypoint (Vite, Webpack, Rollup, Parcel)</strong> — <code>import &#39;@cobalt/components/pre-upgrade.css&#39;;</code> once at the top of the entry alongside other token imports. The bundler extracts it into the page&#39;s preloaded stylesheet.</li><li><strong>Angular</strong> — list the import in <code>src/styles.css</code> or <code>src/styles.scss</code> so the application builder picks it up via <code>angular.json</code>.</li><li><strong>CSS-in-JS hosts (styled-components, Emotion, Stitches)</strong> — load <code>pre-upgrade.css</code> as a global side-effect from your JS entrypoint (same as the Vite/Webpack form). Do not feed the file through the CSS-in-JS pipeline; the runtime might strip <code>:not(:defined)</code> rules thinking nothing in the rendered tree matches them.</li><li><strong>Server-rendered or critical-CSS extracted bundles</strong> — make sure your tooling does not drop <code>:not(:defined)</code> selectors during purge passes. Allowlist the <code>co-*:not(:defined)</code> pattern in your PurgeCSS / Critters / similar configuration if it runs over the migrated slice.</li></ul><h4 id="common-gotchas" tabindex="-1">Common gotchas <a class="header-anchor" href="#common-gotchas" aria-label="Permalink to &quot;Common gotchas&quot;">​</a></h4><ul><li><strong>Lazy-loaded routes.</strong> If the import only lives in a per-route chunk, the flash returns the first time the user navigates into that chunk. Load <code>pre-upgrade.css</code> from the application shell, not per-route.</li><li><strong>Stripped during purge.</strong> Aggressive unused-CSS removal can delete <code>:not(:defined)</code> rules because the live DOM contains zero matching elements when the purger runs. Add <code>co-*:not(:defined)</code> to your safelist.</li><li><strong>Load order regression.</strong> If <code>pre-upgrade.css</code> is moved before <code>@cobalt/tokens/css</code>, every <code>var(--co-*)</code> reference inside the pre-upgrade rules silently falls back to <code>initial</code> and reservations collapse. Keep tokens first.</li><li><strong>Per-route SPA navigation.</strong> Pre-upgrade hides the element until <code>:defined</code>, but the moment the route renders new <code>&lt;co-*&gt;</code> tags from already-registered classes they are already defined — no flash. The mitigation only matters for elements whose component module has not yet been imported. If you lazy-load Cobalt components by route, expect the first navigation into a slice to use the reservation; subsequent navigations are flash-free regardless.</li></ul><h4 id="verifying-it-works" tabindex="-1">Verifying it works <a class="header-anchor" href="#verifying-it-works" aria-label="Permalink to &quot;Verifying it works&quot;">​</a></h4><ul><li>Open DevTools → Sources → search the loaded CSS for <code>:not(:defined)</code>. You should see 28 selectors (one per Cobalt component).</li><li>Throttle the network to &quot;Slow 3G&quot; in DevTools and hard-refresh a migrated page. The chrome reserves space without painting un-styled <code>&lt;co-*&gt;</code> tags, then appears fully styled in a single frame.</li><li>Inspect a <code>&lt;co-button&gt;</code> during the upgrade window. Its computed <code>min-block-size</code> should resolve to a real <code>px</code> value (e.g. <code>40px</code>) sourced from <code>var(--co-control-height-md)</code>. If it does not, your token CSS is loading after the pre-upgrade rules — fix the import order.</li></ul><p>Scope base styles:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-dark-high-contrast github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">&lt;</span><span style="--shiki-dark:#72F088;--shiki-light:#22863A;">main</span><span style="--shiki-dark:#91CBFF;--shiki-light:#6F42C1;"> data-co-base</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">&gt;</span></span>
<span class="line"><span style="--shiki-dark:#BDC4CC;--shiki-light:#6A737D;">  &lt;!-- migrated slice --&gt;</span></span>
<span class="line"><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">&lt;/</span><span style="--shiki-dark:#72F088;--shiki-light:#22863A;">main</span><span style="--shiki-dark:#F0F3F6;--shiki-light:#24292E;">&gt;</span></span></code></pre></div><h2 id="component-adoption" tabindex="-1">Component Adoption <a class="header-anchor" href="#component-adoption" aria-label="Permalink to &quot;Component Adoption&quot;">​</a></h2><p>Start with lower-risk components such as buttons, icons, labels, simple fields, banners, and cards. Keep local or legacy implementations for unsupported app patterns such as dialogs, data grids, date pickers, menus, tabs, pagination, and complex overlays.</p><p>Before replacing a component, check:</p><ul><li>the component page documents the API you need</li><li><a href="/cobalt-design-system/components/status.html">Component Status</a> does not show a blocker for your workflow</li><li>wrapper events and controlled state work in your framework</li><li>keyboard, focus, validation, and accessibility behavior match the current workflow</li><li>there is a fallback if the component is not ready</li></ul><h2 id="framework-examples" tabindex="-1">Framework Examples <a class="header-anchor" href="#framework-examples" aria-label="Permalink to &quot;Framework Examples&quot;">​</a></h2><h3 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h3><p>Keep Bootstrap in place while migrating a route or region. Tokenize local CSS first, then replace simple leaf components. Remove Bootstrap CSS or JavaScript only from bundles that no longer use it.</p><h3 id="angular" tabindex="-1">Angular <a class="header-anchor" href="#angular" aria-label="Permalink to &quot;Angular&quot;">​</a></h3><p>Treat Cobalt as targeted adoption inside the Angular app, not an Angular rewrite. Use <code>@cobalt/angular</code> where wrapper directives help, add <code>CUSTOM_ELEMENTS_SCHEMA</code> where needed, and keep existing Angular Material or local components for unsupported patterns.</p><h3 id="react-vue-and-mui" tabindex="-1">React, Vue, and MUI <a class="header-anchor" href="#react-vue-and-mui" aria-label="Permalink to &quot;React, Vue, and MUI&quot;">​</a></h3><p>Use <code>@cobalt/react</code> or <code>@cobalt/vue</code> when wrappers improve event handling. For MUI or other React libraries, replace a small set of components inside one feature slice instead of attempting a full library swap.</p><h2 id="verification-checklist" tabindex="-1">Verification Checklist <a class="header-anchor" href="#verification-checklist" aria-label="Permalink to &quot;Verification Checklist&quot;">​</a></h2><p>Before calling a slice migrated, verify:</p><ul><li>token and base CSS imports load once and in order</li><li><code>@cobalt/components/pre-upgrade.css</code> is imported alongside the token CSS so <code>co-*</code> elements do not flash unstyled while Lit upgrades them</li><li><code>co doctor</code> returns a clean <code>cobalt.styles.pre-upgrade</code> pass for the migrated slice (run from the project root after wiring the import)</li><li><code>[data-co-base]</code> is scoped to the intended area</li><li>visual review passes against before and after screenshots</li><li>keyboard navigation and focus states work</li><li>labels, descriptions, errors, and required states remain connected</li><li>unit or component tests cover changed state and event behavior</li><li>integration or end-to-end tests cover the migrated workflow</li><li>supported browsers and themes are checked</li><li>unsupported patterns are documented as deferred or roadmap gaps</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/cobalt-design-system/guidance/adoption.html">Adoption Plan</a></li><li><a href="/cobalt-design-system/guidance/element-mapping.html">Element Mapping</a></li><li><a href="/cobalt-design-system/tokens/">Token Reference</a></li><li><a href="/cobalt-design-system/foundations/css-layers.html">CSS Cascade Layers</a></li><li><a href="/cobalt-design-system/components/status.html">Component Status</a></li><li><a href="/cobalt-design-system/resources/cli.html#manage-the-cobalt-skill">Manage the Cobalt Skill</a></li></ul>`,43)])])}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
